const {origin,destination,date}=$input.first().json.body ?? {};
const stamp=Date.parse(date);
if (!/^[A-Z]{3}$/.test(origin ?? '') || !/^[A-Z]{3}$/.test(destination ?? '') || origin===destination ||
    !/^20\d\d-\d\d-\d\d$/.test(date ?? '') || !Number.isFinite(stamp) || new Date(stamp).toISOString().slice(0,10)!==date ||
    stamp<Date.now()-86400000 || stamp>Date.now()+365*86400000) throw Error('Invalid flight query');
return [{json:{origin,destination,date}}];

const query=$('Validasi rute dan tanggal').first().json;
const response=$input.first().json;
if (response.isError) throw Error('FlightClaw search failed');
let result=response.structuredContent ?? response;
if (!Array.isArray(result.offers)) {
  const texts=(Array.isArray(response.content)?response.content:[]).filter(item=>item.type==='text');
  if (texts.length===1) try { result=JSON.parse(texts[0].text); } catch {}
}
if (!Array.isArray(result.offers)) throw Error('FlightClaw offers missing');
const now=Date.now();
const offers=result.offers.flatMap(offer=>{
  const leg=offer.slices?.[0], total=Number(offer.total_amount);
  if (offer.slices?.length!==1 || leg?.origin!==query.origin || leg.destination!==query.destination ||
      !leg.departing_at?.startsWith(query.date+'T') || !offer.payable || !(Date.parse(offer.expires_at)>now) ||
      !Number.isFinite(total) || total<=0 || !/^[A-Z]{3}$/.test(offer.currency ?? '') ||
      typeof offer.airline?.name!=='string' || !Number.isInteger(leg.stops) || leg.stops<0) return [];
  return [{total,currency:offer.currency,airline:offer.airline.name,stops:leg.stops,
    departure:leg.departing_at.slice(11,16),arrival:leg.arriving_at?.slice(11,16)}];
});
if (result.offers.length && !offers.length) throw Error('No usable FlightClaw offers');
const currency=offers[0]?.currency;
return [{json:{...query,offers:offers.filter(offer=>offer.currency===currency).sort((a,b)=>a.total-b.total).slice(0,5)}}];
